INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 23, 'theory', 'Quiz: Food Delivery');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 23, 0, 'Why must a second tap on the "Place order" button not create a second order?', '["It does not matter", "The request is idempotent: it carries a key, and a retry returns the order already created", "The server cannot keep up", "The button is blocked forever"]', 1, 'A duplicated order means a loss and an unhappy customer; an idempotency key makes the retry safe.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 23, 1, 'How is payment for an order structured?', '["A single charge right away", "Pre-authorization, confirmation by the restaurant, charge after delivery; cancels and refunds are saga compensations", "Cash to the courier", "Manually only"]', 1, 'Every step has a reverse action, and requests to the gateway are idempotent.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 23, 2, 'How is a courier chosen?', '["At random", "By position from the geo service, load, and time to arrive, with atomic assignment", "Alphabetically", "By the restaurant''s rating"]', 1, 'The assignment is atomic and idempotent: two couriers for one order are unacceptable.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 23, 3, 'Why must the restaurant confirm the order?', '["For statistics", "So orders are not lost: no confirmation in time — the order goes to an operator or is canceled with a refund", "To slow the service down", "For advertising"]', 1, 'Partner systems are unreliable, so confirmation, a timeout, and a fallback channel are needed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 23, 4, 'What protects the main order path at the lunch peak?', '["Nothing", "A fleet prepared ahead of time, queues, limiters and priorities, degradation of secondary features", "Switching the database off", "Raising prices"]', 1, 'The critical path — checkout, payment, and hand-off to the restaurant — must work under any conditions.');
